INSERT INTO `towers` (`idx`, `tower_name`, `base_damage`, `base_range`, `base_build_cost`, `base_type`, `attack_type`, `base_cooldown`, `base_upgrade_cost`, `tier`, `description`, `attack_effect_file`, `damage_growth`, `cost_growth`) VALUES
	(101, '코로몬', 20, 130, 100, 'FIRE', 'SINGLE', 0.85, 150, 1, '작은 불꽃을 뱉어 공격합니다.', '101', 1.05, 1.10),
	(102, '아구몬', 60, 140, 500, 'FIRE', 'SINGLE', 0.90, 400, 2, '화염의 힘으로 적을 태웁니다.', '102', 1.05, 1.10),
	(103, '그레이몬', 180, 150, 1500, 'FIRE', 'SINGLE', 0.95, 1200, 3, '거대한 화염으로 적을 압도합니다.', '103', 1.05, 1.10),
	(104, '메탈그레이몬', 400, 160, 5000, 'FIRE', 'MULTI', 1.00, 3600, 4, '초고열의 에너지로 모든 것을 소멸시킵니다.', '104', 1.05, 1.10),
	(201, '뿔몬', 15, 140, 100, 'WATER', 'SLOW', 1.20, 180, 1, '적에게 물을 뿌려 움직임을 둔하게 만듭니다.', '201', 1.05, 1.10),
	(202, '파피몬', 45, 150, 500, 'WATER', 'SLOW', 1.10, 450, 2, '차가운 입김으로 적을 얼어붙게 합니다.', '202', 1.05, 1.10),
	(203, '가루몬', 135, 160, 1500, 'WATER', 'SLOW', 1.00, 1300, 3, '푸른 화염으로 적의 속도를 크게 늦춥니다.', '203', 1.05, 1.10),
	(204, '워가루몬', 450, 180, 5000, 'WATER', 'SLOW', 0.90, 3900, 4, '절대영도의 냉기로 적을 정지 수준으로 만듭니다.', '204', 1.05, 1.10),
	(301, '시드몬', 12, 120, 100, 'PLANT', 'MULTI', 1.50, 200, 1, '씨앗을 흩뿌려 주변 적들을 공격합니다.', '301', 1.05, 1.10),
	(302, '팔몬', 36, 130, 500, 'PLANT', 'MULTI', 1.40, 500, 2, '독 줄기를 뻗어 다수의 적을 타격합니다.', '302', 1.05, 1.10),
	(303, '니드몬', 120, 140, 1500, 'PLANT', 'MULTI', 1.30, 1500, 3, '바늘 뿜기로 넓은 범위의 적을 공격합니다.', '303', 1.05, 1.10),
	(304, '릴리몬', 360, 150, 5000, 'PLANT', 'MULTI', 1.20, 4500, 4, '꽃잎포로 전장의 적들을 쓸어버립니다.', '304', 1.05, 1.10),
	(401, '모티몬', 12, 130, 100, 'ELECTRIC', 'STUN', 2.00, 190, 1, '약한 전기로 적을 깜짝 놀라게 합니다.', '401', 1.05, 1.10),
	(402, '텐타몬', 36, 140, 500, 'ELECTRIC', 'STUN', 1.80, 480, 2, '전기를 방출하여 적을 잠시 마비시킵니다.', '402', 1.05, 1.10),
