-- 테이블 dtd_project.user_inventory 구조 내보내기
DROP TABLE IF EXISTS `user_inventory`;
CREATE TABLE IF NOT EXISTS `user_inventory` (
  `user_idx` bigint(20) NOT NULL COMMENT '유저 IDX 참조',
